import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 7
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    records = list(reader)

    def is_blank(record):
        return not record or all(not value.strip() for value in record)

    def is_header_candidate(record):
        if len(record) != expected_width:
            return False
        first = record[0].lstrip("\ufeff").lstrip()
        if first.startswith("#"):
            values = [first[1:].strip()] + [value.strip() for value in record[1:]]
            return all(
                not value or re.fullmatch(r"[A-Za-z][A-Za-z0-9 _-]*", value)
                for value in values
            )
        values = [value.strip() for value in record]
        return (
            all(value and re.fullmatch(r"[A-Za-z][A-Za-z0-9 _-]*", value) for value in values)
            and any(value.upper() == value and any(char.isalpha() for char in value) for value in values)
        )

    header_index = next(
        (index for index, record in enumerate(records) if is_header_candidate(record)),
        None,
    )

    if header_index is None:
        header_index = next(
            (index for index, record in enumerate(records) if not is_blank(record)),
            None,
        )

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = list(records[header_index])
    columns[0] = columns[0].lstrip("\ufeff").strip()
    if columns[0].startswith("#"):
        columns[0] = columns[0][1:].strip()

    if len(columns) < expected_width:
        columns.extend([""] * (expected_width - len(columns)))
    elif len(columns) > expected_width:
        columns = columns[:expected_width - 1] + [",".join(columns[expected_width - 1:])]

    rows = []
    for record in records[header_index + 1:]:
        if is_blank(record):
            continue
        values = list(record)
        if len(values) < expected_width:
            values.extend([""] * (expected_width - len(values)))
        elif len(values) > expected_width:
            values = values[:expected_width - 1] + [",".join(values[expected_width - 1:])]
        rows.append(values)

    return {"columns": columns, "rows": rows}
